package com.edu.registration.controller;

import com.edu.registration.entity.*;
import com.edu.registration.exception.ApiException;
import com.edu.registration.repository.*;
import com.edu.registration.security.CurrentUser;
import com.edu.registration.service.TienDoService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.time.LocalDateTime;
import java.util.*;

@RestController @RequestMapping("/api")
public class TienDoController {
 private final TienDoService progress; private final ChuongTrinhDaoTaoRepository programs; private final NganhRepository majors; private final MonHocRepository subjects;
 private final SinhVienRepository students; private final CurrentUser current; private final KeHoachCaNhanRepository plans; private final LopHocPhanRepository classes;
 private final DangKyHocPhanRepository registrations; private final DiemRepository grades; private final MonTienQuyetRepository prereqs;
 public TienDoController(TienDoService p,ChuongTrinhDaoTaoRepository pr,NganhRepository m,MonHocRepository s,SinhVienRepository st,CurrentUser c,KeHoachCaNhanRepository kp,LopHocPhanRepository cl,DangKyHocPhanRepository r,DiemRepository g,MonTienQuyetRepository q){progress=p;programs=pr;majors=m;subjects=s;students=st;current=c;plans=kp;classes=cl;registrations=r;grades=g;prereqs=q;}
 @GetMapping("/sinh-vien/me/tien-do") @PreAuthorize("hasRole('SINH_VIEN')") public Map<String,Object> progress(){return progress.get();}
 public record GroupRequest(String name,NhomChuongTrinh.LoaiNhom type,int requiredCredits,List<Long> subjectIds){}
 public record ProgramRequest(Long majorId,String cohort,String version,List<GroupRequest> groups){}
 @GetMapping("/admin/chuong-trinh") @PreAuthorize("hasRole('QUAN_TRI')") public List<Map<String,Object>> listPrograms(){return programs.findAll().stream().map(p->Map.<String,Object>of("id",p.getId(),"majorId",p.getNganh().getId(),"major",p.getNganh().getTen(),"cohort",p.getKhoaNhapHoc(),"version",p.getPhienBan(),"groups",p.getNhom().size())).toList();}
 @PostMapping("/admin/chuong-trinh") @PreAuthorize("hasRole('QUAN_TRI')") @Transactional public Map<String,Object> createProgram(@RequestBody ProgramRequest req){
  if(req.cohort()==null||req.cohort().isBlank()||req.version()==null||req.version().isBlank()||req.groups()==null||req.groups().isEmpty())throw ApiException.badRequest("Cần ngành, khóa, phiên bản và ít nhất một nhóm môn.");
  ChuongTrinhDaoTao p=new ChuongTrinhDaoTao();p.setNganh(majors.findById(req.majorId()).orElseThrow(()->ApiException.notFound("Ngành không tồn tại")));p.setKhoaNhapHoc(req.cohort().trim());p.setPhienBan(req.version().trim());Set<Long> used=new HashSet<>();
  for(GroupRequest g:req.groups()){if(g.name()==null||g.name().isBlank()||g.requiredCredits()<0)throw ApiException.badRequest("Thông tin nhóm môn không hợp lệ.");NhomChuongTrinh n=new NhomChuongTrinh();n.setChuongTrinh(p);n.setTen(g.name().trim());n.setLoai(g.type());n.setTinChiYeuCau(g.requiredCredits());for(Long id:g.subjectIds()==null?List.<Long>of():g.subjectIds()){if(!used.add(id))throw ApiException.badRequest("Không thể đưa một môn vào nhiều nhóm để tránh tính trùng.");n.getMonHoc().add(subjects.findById(id).orElseThrow(()->ApiException.notFound("Môn học không tồn tại")));}p.getNhom().add(n);}
  p=programs.save(p);return Map.of("id",p.getId(),"message","Đã lưu chương trình.");
 }
 @PutMapping("/admin/sinh-vien/{studentId}/chuong-trinh/{programId}") @PreAuthorize("hasRole('QUAN_TRI')") @Transactional public void assign(@PathVariable Long studentId,@PathVariable Long programId){SinhVien sv=students.findById(studentId).orElseThrow(()->ApiException.notFound("Sinh viên không tồn tại"));ChuongTrinhDaoTao p=programs.findById(programId).orElseThrow(()->ApiException.notFound("Chương trình không tồn tại"));if(sv.getNganh()==null||!sv.getNganh().getId().equals(p.getNganh().getId()))throw ApiException.badRequest("Chương trình phải thuộc đúng ngành của sinh viên.");sv.setChuongTrinh(p);students.save(sv);}
 @GetMapping("/sinh-vien/me/ke-hoach") @PreAuthorize("hasRole('SINH_VIEN')") public List<Map<String,Object>> plans(){SinhVien sv=student();return plans.findBySinhVienIdOrderByCapNhatLucDesc(sv.getId()).stream().map(this::planDto).toList();}
 public record PlanRequest(String name,List<Long> classIds){}
 @PostMapping("/sinh-vien/me/ke-hoach") @PreAuthorize("hasRole('SINH_VIEN')") @Transactional public Map<String,Object> createPlan(@RequestBody PlanRequest req){if(req.name()==null||req.name().isBlank())throw ApiException.badRequest("Tên kế hoạch không được để trống.");KeHoachCaNhan p=new KeHoachCaNhan();p.setSinhVien(student());p.setTen(req.name().trim());updateItems(p,req.classIds());return planDto(plans.save(p));}
 @PutMapping("/sinh-vien/me/ke-hoach/{id}") @PreAuthorize("hasRole('SINH_VIEN')") @Transactional public Map<String,Object> updatePlan(@PathVariable Long id,@RequestBody PlanRequest req){KeHoachCaNhan p=plans.findByIdAndSinhVienId(id,student().getId()).orElseThrow(()->ApiException.notFound("Không tìm thấy kế hoạch"));if(req.name()!=null&&!req.name().isBlank())p.setTen(req.name().trim());p.setCapNhatLuc(LocalDateTime.now());updateItems(p,req.classIds());return planDto(plans.save(p));}
 @DeleteMapping("/sinh-vien/me/ke-hoach/{id}") @PreAuthorize("hasRole('SINH_VIEN')") @Transactional public void deletePlan(@PathVariable Long id){KeHoachCaNhan p=plans.findByIdAndSinhVienId(id,student().getId()).orElseThrow(()->ApiException.notFound("Không tìm thấy kế hoạch"));plans.delete(p);}
 @GetMapping("/sinh-vien/me/goi-y-ke-hoach") @PreAuthorize("hasRole('SINH_VIEN')") public List<Map<String,Object>> suggestions(){
  Map<String,Object> prog=progress.get(); if(!Boolean.TRUE.equals(prog.get("configured")))return List.of();
  Set<Long> inProgram=new HashSet<>(), completed=new HashSet<>();
  for(Object go:(List<?>)prog.get("groups"))for(Object co:(List<?>)((Map<?,?>)go).get("courses")){Map<?,?> c=(Map<?,?>)co;long id=((Number)c.get("id")).longValue();inProgram.add(id);if("PASSED".equals(c.get("status")))completed.add(id);}
  SinhVien sv=student();Set<Long> passed=new HashSet<>(grades.findMonDaDat(sv.getId(),5.0));
  List<DangKyHocPhan> activeRegistrations=registrations.findAllActiveOfStudent(sv.getId(),TrangThaiDangKy.DA_DANG_KY);
  Set<Long> registered=new HashSet<>(activeRegistrations.stream().map(d->d.getLopHocPhan().getMonHoc().getId()).toList());
  List<LopHocPhan> candidates=classes.findOpenForRegistration(java.time.LocalDate.now()).stream().filter(l->inProgram.contains(l.getMonHoc().getId())&&!completed.contains(l.getMonHoc().getId())&&!registered.contains(l.getMonHoc().getId())&&activeRegistrations.stream().noneMatch(r->r.getLopHocPhan().getHocKy().getId().equals(l.getHocKy().getId())&&r.getLopHocPhan().trungLichVoi(l))).toList();
  if(candidates.isEmpty())return List.of();
  Map<Long,List<MonTienQuyet>> requirements=prereqs.findByMonHocIdInOrderByIdAsc(candidates.stream().map(l->l.getMonHoc().getId()).distinct().toList()).stream().collect(java.util.stream.Collectors.groupingBy(q->q.getMonHoc().getId()));
  List<Map<String,Object>> out=new ArrayList<>();for(LopHocPhan l:candidates){if(requirements.getOrDefault(l.getMonHoc().getId(),List.of()).stream().anyMatch(q->!passed.contains(q.getMonTienQuyet().getId())))continue;Map<String,Object> item=new LinkedHashMap<>();item.put("classId",l.getId());item.put("classCode",l.getMa());item.put("subjectId",l.getMonHoc().getId());item.put("subjectCode",l.getMonHoc().getMa());item.put("subjectName",l.getMonHoc().getTen());item.put("credits",l.getMonHoc().getSoTinChi());item.put("semester",l.getHocKy().getTen()+" "+l.getHocKy().getNamHoc());item.put("semesterId",l.getHocKy().getId());item.put("day",l.getThu());item.put("startPeriod",l.getTietBatDau());item.put("periods",l.getSoTiet());item.put("remainingSeats",l.getConLai());item.put("reason","Còn thiếu trong chương trình; lớp đang mở đăng ký và các môn tiên quyết đã đạt.");out.add(item);}return out;}
 private void updateItems(KeHoachCaNhan plan,List<Long> ids){plan.getMon().clear();if(ids==null)return;Map<String,Object> state=progress.get();if(!Boolean.TRUE.equals(state.get("configured")))throw ApiException.badRequest("Cần cấu hình chương trình trước khi lập kế hoạch.");Set<Long> eligible=new HashSet<>(),passed=new HashSet<>();for(Object g:(List<?>)state.get("groups"))for(Object c:(List<?>)((Map<?,?>)g).get("courses")){Map<?,?> course=(Map<?,?>)c;long cid=((Number)course.get("id")).longValue();if("PASSED".equals(course.get("status")))passed.add(cid);else eligible.add(cid);}Set<Long> alreadyPassed=new HashSet<>(grades.findMonDaDat(plan.getSinhVien().getId(),5.0));List<DangKyHocPhan> active=registrations.findAllActiveOfStudent(plan.getSinhVien().getId(),TrangThaiDangKy.DA_DANG_KY);Set<Long> uniq=new HashSet<>();List<LopHocPhan> chosen=new ArrayList<>();Map<Long,Integer> plannedCredits=new HashMap<>();for(Long id:ids){if(!uniq.add(id))throw ApiException.badRequest("Lớp bị lặp trong kế hoạch.");LopHocPhan l=classes.findWithDetailsById(id).orElseThrow(()->ApiException.notFound("Lớp học phần không tồn tại"));Long subjectId=l.getMonHoc().getId();if(!eligible.contains(subjectId)||passed.contains(subjectId))throw ApiException.badRequest("Chỉ lập kế hoạch cho môn còn thiếu trong chương trình.");if(!l.getHocKy().dangMoDangKy()||l.getConLai()==0)throw ApiException.badRequest("Chỉ lưu lớp đang mở đăng ký và còn chỗ.");if(prereqs.findByMonHocIdOrderByIdAsc(subjectId).stream().anyMatch(q->!alreadyPassed.contains(q.getMonTienQuyet().getId())))throw ApiException.badRequest("Chưa đạt đủ môn tiên quyết.");if(active.stream().anyMatch(r->r.getLopHocPhan().getHocKy().getId().equals(l.getHocKy().getId())&&(r.getLopHocPhan().getMonHoc().getId().equals(subjectId)||r.getLopHocPhan().trungLichVoi(l))))throw ApiException.badRequest("Lớp xung đột với môn đã đăng ký trong học kỳ.");if(chosen.stream().anyMatch(c->c.getHocKy().getId().equals(l.getHocKy().getId())&&(c.getMonHoc().getId().equals(subjectId)||c.trungLichVoi(l))))throw ApiException.badRequest("Kế hoạch có môn trùng hoặc xung đột lịch.");int used=plannedCredits.getOrDefault(l.getHocKy().getId(),(int)registrations.tinhTongTinChi(plan.getSinhVien().getId(),l.getHocKy().getId(),TrangThaiDangKy.DA_DANG_KY));if(used+l.getMonHoc().getSoTinChi()>l.getHocKy().getSoTinChiToiDa())throw ApiException.badRequest("Vượt giới hạn tín chỉ của học kỳ đã cấu hình.");plannedCredits.put(l.getHocKy().getId(),used+l.getMonHoc().getSoTinChi());chosen.add(l);KeHoachMon item=new KeHoachMon();item.setKeHoach(plan);item.setLopHocPhan(l);plan.getMon().add(item);}}
 private Map<String,Object> planDto(KeHoachCaNhan p){List<Map<String,Object>> items=p.getMon().stream().map(i->Map.<String,Object>of("classId",i.getLopHocPhan().getId(),"classCode",i.getLopHocPhan().getMa(),"subject",i.getLopHocPhan().getMonHoc().getTen(),"semester",i.getLopHocPhan().getHocKy().getTen()+" "+i.getLopHocPhan().getHocKy().getNamHoc(),"semesterId",i.getLopHocPhan().getHocKy().getId())).toList();return Map.of("id",p.getId(),"name",p.getTen(),"updatedAt",p.getCapNhatLuc(),"items",items,"tentative",true);}
 private SinhVien student(){return students.findByUser(current.get()).orElseThrow(()->ApiException.notFound("Không tìm thấy hồ sơ sinh viên"));}
}
